define_hashmap!(HashMapBoolU8, bool, u8, u8::MAX);
define_hashmap!(HashMapBoolU16, bool, u16, u16::MAX);
define_hashmap!(HashMapBoolU32, bool, u32, u32::MAX);
define_hashmap!(HashMapBoolU64, bool, u64, u64::MAX);
define_hashmap!(HashMapBoolF32, bool, f32, f32::NAN);
define_hashmap!(HashMapBoolF64, bool, f64, f64::NAN);

