define_hashmap!(HashMapU64F64, u64, f64, f64::NAN);

#[pymodule]
fn _native(m: &Bound<'_, PyModule>) -> PyResult<()> {
    // bool key
    m.add_class::<HashMapBoolBool>()?;
    m.add_class::<HashMapBoolI8>()?;
    m.add_class::<HashMapBoolI16>()?;
    m.add_class::<HashMapBoolI32>()?;
    m.add_class::<HashMapBoolI64>()?;
    m.add_class::<HashMapBoolU8>()?;
    m.add_class::<HashMapBoolU16>()?;
    m.add_class::<HashMapBoolU32>()?;
    m.add_class::<HashMapBoolU64>()?;
    m.add_class::<HashMapBoolF32>()?;
    m.add_class::<HashMapBoolF64>()?;

    // i8 key
    m.add_class::<HashMapI8Bool>()?;
    m.add_class::<HashMapI8I8>()?;
    m.add_class::<HashMapI8I16>()?;
    m.add_class::<HashMapI8I32>()?;
    m.add_class::<HashMapI8I64>()?;
    m.add_class::<HashMapI8U8>()?;
    m.add_class::<HashMapI8U16>()?;
    m.add_class::<HashMapI8U32>()?;
    m.add_class::<HashMapI8U64>()?;
    m.add_class::<HashMapI8F32>()?;
    m.add_class::<HashMapI8F64>()?;

    // i16 key
    m.add_class::<HashMapI16Bool>()?;
    m.add_class::<HashMapI16I8>()?;
    m.add_class::<HashMapI16I16>()?;
    m.add_class::<HashMapI16I32>()?;
    m.add_class::<HashMapI16I64>()?;
    m.add_class::<HashMapI16U8>()?;
    m.add_class::<HashMapI16U16>()?;
    m.add_class::<HashMapI16U32>()?;
    m.add_class::<HashMapI16U64>()?;
    m.add_class::<HashMapI16F32>()?;
    m.add_class::<HashMapI16F64>()?;

    // i32 key
    m.add_class::<HashMapI32Bool>()?;
    m.add_class::<HashMapI32I8>()?;
    m.add_class::<HashMapI32I16>()?;
    m.add_class::<HashMapI32I32>()?;
    m.add_class::<HashMapI32I64>()?;
    m.add_class::<HashMapI32U8>()?;
    m.add_class::<HashMapI32U16>()?;
    m.add_class::<HashMapI32U32>()?;
    m.add_class::<HashMapI32U64>()?;
    m.add_class::<HashMapI32F32>()?;
    m.add_class::<HashMapI32F64>()?;

    // i64 key
    m.add_class::<HashMapI64Bool>()?;
    m.add_class::<HashMapI64I8>()?;
    m.add_class::<HashMapI64I16>()?;
    m.add_class::<HashMapI64I32>()?;
    m.add_class::<HashMapI64I64>()?;
    m.add_class::<HashMapI64U8>()?;
    m.add_class::<HashMapI64U16>()?;
    m.add_class::<HashMapI64U32>()?;
    m.add_class::<HashMapI64U64>()?;
    m.add_class::<HashMapI64F32>()?;
    m.add_class::<HashMapI64F64>()?;

    // u8 key
    m.add_class::<HashMapU8Bool>()?;
    m.add_class::<HashMapU8I8>()?;
    m.add_class::<HashMapU8I16>()?;
    m.add_class::<HashMapU8I32>()?;
    m.add_class::<HashMapU8I64>()?;
    m.add_class::<HashMapU8U8>()?;
    m.add_class::<HashMapU8U16>()?;
    m.add_class::<HashMapU8U32>()?;
    m.add_class::<HashMapU8U64>()?;
    m.add_class::<HashMapU8F32>()?;
    m.add_class::<HashMapU8F64>()?;

    // u16 key
    m.add_class::<HashMapU16Bool>()?;
    m.add_class::<HashMapU16I8>()?;
    m.add_class::<HashMapU16I16>()?;
    m.add_class::<HashMapU16I32>()?;
    m.add_class::<HashMapU16I64>()?;
    m.add_class::<HashMapU16U8>()?;
    m.add_class::<HashMapU16U16>()?;
    m.add_class::<HashMapU16U32>()?;
    m.add_class::<HashMapU16U64>()?;
    m.add_class::<HashMapU16F32>()?;
    m.add_class::<HashMapU16F64>()?;

    // u32 key
    m.add_class::<HashMapU32Bool>()?;
    m.add_class::<HashMapU32I8>()?;
    m.add_class::<HashMapU32I16>()?;
    m.add_class::<HashMapU32I32>()?;
    m.add_class::<HashMapU32I64>()?;
    m.add_class::<HashMapU32U8>()?;
    m.add_class::<HashMapU32U16>()?;
    m.add_class::<HashMapU32U32>()?;
    m.add_class::<HashMapU32U64>()?;
    m.add_class::<HashMapU32F32>()?;
    m.add_class::<HashMapU32F64>()?;

    // u64 key
    m.add_class::<HashMapU64Bool>()?;
    m.add_class::<HashMapU64I8>()?;
    m.add_class::<HashMapU64I16>()?;
    m.add_class::<HashMapU64I32>()?;
    m.add_class::<HashMapU64I64>()?;
    m.add_class::<HashMapU64U8>()?;
    m.add_class::<HashMapU64U16>()?;
    m.add_class::<HashMapU64U32>()?;
    m.add_class::<HashMapU64U64>()?;
    m.add_class::<HashMapU64F32>()?;
    m.add_class::<HashMapU64F64>()?;

    // Per-segment distinct-value count kernel (CSR-grouped np.unique
    // replacement). See `segment_distinct.rs`.
    m.add_function(wrap_pyfunction!(segment_distinct_count, m)?)?;

    // Per-row identity FID/counter remap walk kernel (ALG-3/4/9). See
    // `remap_walk.rs`.
    m.add_function(wrap_pyfunction!(apply_remap_walk, m)?)?;

    // Stage-3c NUMBER-band idx_2d emission kernel (ALG-2/7/8). See
    // `number_idx_2d.rs`.
    m.add_function(wrap_pyfunction!(build_number_idx_2d_kernel, m)?)?;

    // Stage-3 per-source carrier-sign collection kernel. See
    // `carrier_signs.rs`.
    m.add_function(wrap_pyfunction!(build_carrier_signs_kernel, m)?)?;

    // Stage-3b identity carrier gather kernel (ALG-5 front matter). See
    // `identity_gather.rs`.
    m.add_function(wrap_pyfunction!(build_identity_carriers_kernel, m)?)?;

    // Stage-3a surviving inline-byte gather kernel (ALG-1). See
    // `inline_bytes.rs`.
    m.add_function(wrap_pyfunction!(build_inline_bytes_kernel, m)?)?;

    // Stage-3c NUMBER-band flat-segment column build (the per-kept-node
    // DenseColumns slice + concat feeding the number idx_2d kernel). See
    // `flat_segments.rs`.
    m.add_function(wrap_pyfunction!(build_flat_segments_kernel, m)?)?;

    Ok(())
}
